import React from "react";
import { Routes, Route, Navigate, useLocation } from "react-router-dom";
import Navbar from "components/navbar";
import Sidebar from "components/sidebar";
import Footer from "components/footer/Footer";
import ProtectedRoute from "components/ProtectedRoute";
import HotelStaffRoutes from "routes/hotel-staff";

export default function HotelStaffLayout(props) {
    const { ...rest } = props;
    const location = useLocation();
    const [open, setOpen] = React.useState(true);
    const [currentRoute, setCurrentRoute] = React.useState("Check-in/Check-out");

    React.useEffect(() => {
        window.addEventListener("resize", () =>
            window.innerWidth < 1200 ? setOpen(false) : setOpen(true)
        );
    }, []);

    React.useEffect(() => {
        getActiveRoute(HotelStaffRoutes);
    }, [location.pathname]);

    const getActiveRoute = (routes) => {
        let activeRoute = "Check-in/Check-out";
        for (let i = 0; i < routes.length; i++) {
            if (
                window.location.href.indexOf(
                    routes[i].layout + "/" + routes[i].path
                ) !== -1
            ) {
                setCurrentRoute(routes[i].name);
            }
        }
        return activeRoute;
    };

    const getActiveNavbar = (routes) => {
        let activeNavbar = false;
        for (let i = 0; i < routes.length; i++) {
            if (
                window.location.href.indexOf(routes[i].layout + routes[i].path) !== -1
            ) {
                return routes[i].secondary;
            }
        }
        return activeNavbar;
    };

    const getRoutes = (routes) => {
        return routes.map((prop, key) => {
            if (prop.layout === "/hotel-staff") {
                return (
                    <Route path={`/${prop.path}`} element={prop.component} key={key} />
                );
            } else {
                return null;
            }
        });
    };

    document.documentElement.dir = "ltr";
    return (
        <ProtectedRoute requiredRole="hotel_staff">
            <div className="flex h-full w-full">
                <Sidebar open={open} onClose={() => setOpen(false)} routes={HotelStaffRoutes} />
                {/* Navbar & Main Content */}
                <div className="h-full w-full bg-lightPrimary dark:!bg-navy-900">
                    {/* Main Content */}
                    <main
                        className={`mx-[12px] h-full flex-none transition-all md:pr-2 xl:ml-[313px]`}
                    >
                        {/* Routes */}
                        <div className="h-full">
                            <Navbar
                                onOpenSidenav={() => setOpen(true)}
                                logoText={"Hotel Management"}
                                brandText={currentRoute}
                                secondary={getActiveNavbar(HotelStaffRoutes)}
                                {...rest}
                            />
                            <div className="pt-5s mx-auto mb-auto h-full min-h-[84vh] p-2 md:pr-2">
                                <Routes>
                                    {getRoutes(HotelStaffRoutes)}
                                    <Route
                                        path="/"
                                        element={<Navigate to="/hotel-staff/checkin-checkout" replace />}
                                    />
                                </Routes>
                            </div>
                            <div className="p-3">
                                <Footer />
                            </div>
                        </div>
                    </main>
                </div>
            </div>
        </ProtectedRoute>
    );
}
